pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_array: Vec<i64> = match input {
        serde_json::Value::Array(arr) => arr.into_iter().map(|v| v.as_i64().unwrap()).collect(),
        _ => panic!("Input must be an array"),
    };

    let cents = input_array[0];
    let n = input_array[1];

    // Validate inputs
    if cents < 0 || n < 1 || n > 64 {
        panic!("Invalid input: cents must be nonnegative and n >= 1, n <= 64");
    }

    // Calculate base share and remainder
    let base = cents / n;
    let remainder = cents % n;

    // Create shares: remainder shares of (base + 1), rest of base
    let mut shares = vec![base; n];
    for i in 0..remainder {
        shares[i] += 1;
    }

    // Convert back to JSON array
    serde_json::to_value(shares).unwrap()
}
